<?php
namespace App\Repositories\Eloquent; use App\Models\Product; use App\Repositories\Contracts\ProductRepository; use Illuminate\Contracts\Pagination\LengthAwarePaginator;
class EloquentProductRepository implements ProductRepository { public function search(array $f):LengthAwarePaginator { return Product::query()->with(['vendor','category','images','inventory'])->available()->when($f['q']??null,fn($q,$v)=>$q->where('name','like',"%{$v}%"))->when($f['category']??null,fn($q,$v)=>$q->whereHas('category',fn($c)=>$c->where('slug',$v)))->when($f['vendor']??null,fn($q,$v)=>$q->whereHas('vendor',fn($s)=>$s->where('slug',$v)))->when($f['location']??null,fn($q,$v)=>$q->whereHas('vendor',fn($s)=>$s->where('location','like',"%{$v}%")))->when($f['min_price']??null,fn($q,$v)=>$q->where('price','>=',$v))->when($f['max_price']??null,fn($q,$v)=>$q->where('price','<=',$v))->latest()->paginate(min((int)($f['per_page']??15),50))->withQueryString(); } public function findPublic(string $slug):Product{return Product::with(['vendor','category','images','inventory','reviews.user'])->available()->where('slug',$slug)->firstOrFail();} }
